  if(item.transactionIds?.length){openDetail('transactions',null,'',item.transactionIds);return}
  if(['AMOUNT LEFT DECREASED','AMOUNT LEFT TREND','SPENDING ROUTINE SHIFTED'].includes(type)){document.querySelector('#incomePanel')?.scrollIntoView({behavior:'smooth',block:'start'});return}
  if(['CATEGORY SPENDING INCREASED','CATEGORY ROUTINE SHIFTED'].includes(type)){if((activeGroup.items||[]).length===1)openCategoryTransactions(item.label,null);else openDetail('categories',null);return}
  if(['RECURRING AMOUNT INCREASED','FEE AMOUNT INCREASED','FIRST FEE OBSERVED','RECURRING BURDEN SHIFTED','PERSISTENT INSTALLMENT BURDEN'].includes(type)){openRecurringModal('series');return}
